int temperature;
int led_state;
void init() { temperature = 0; led_state = 0; }
int read_temperature() { int temp = rand() % 50; return temp; }
void update_led() { if (temperature > MAX_TEMP) led_state = 1; else led_state = 0; }
void print_status() { printf("Temp: %d, LED: %d\n", temperature, led_state); }
int main() {
    init();
    while (1) { temperature = read_temperature(); update_led(); print_status(); }
}

